/* === FORMAT RAG KNOWLEDGE RESPONSE & CALIBRATED EVIDENCE GATE (DEPI-ONLY) === */
const inputItems = $input.all().map(item => item.json || {});
const rows = inputItems.flatMap(item => Array.isArray(item) ? item : (Array.isArray(item.results) ? item.results : [item]));
const detectorData = $('Program Detector & Query Normalizer').first()?.json || {};
const locale = detectorData.locale || 'ar';
const isAr = locale === 'ar';
const programScope = detectorData.program_scope || 'DEPI';
const isOutOfScope = Boolean(detectorData.is_out_of_scope);
const topicCategory = detectorData.topic_category || '';
const customerMsg = detectorData.customer_message || '';
const normLower = (detectorData.normalized_message || customerMsg).toLowerCase();

// --- MODIFIED: Ensure out-of-scope is handled strictly first ---
if (isOutOfScope) {
  return [{
    json: {
      status: 'out_of_scope',
      action: 'SAFE_DEFLECTION',
      intent_handled: 'faq_query', // Still an FAQ type query, but out of scope
      program_scope: programScope,
      is_ambiguous: false,
      is_out_of_scope: true,
      rag_context: '',
      curated_answer: detectorData.out_of_scope_reply,
      evidence_supported: false,
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0,
      confidence: 'none',
      confidence_label: 'NONE',
      retrieval_status: 'out_of_scope_initiative',
      request_id: detectorData.request_id || null,
      execution_id: detectorData.execution_id || null,
      channel: detectorData.channel || 'webchat',
      channel_user_id: detectorData.channel_user_id || null,
      customer: detectorData.customer || null,
      conversation: detectorData.conversation || null,
      ai_output: detectorData.ai_output || {},
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: 'out_of_scope' }
    }
  }];
}
// --- END MODIFIED ---

// 2. Calibrate Retrieved Rows - Strictly DEPI records
const relevant = rows.filter(r => r && (r.relevance_score || 0) > 0 && ((r.program === 'DEPI' && r.retrieval_scope === 'DEPI_AUTHORITATIVE') || (r.program === 'COMMON' && r.retrieval_scope === 'GENERAL_SUPPORT')));

// Hard Negative / Unsupported Claim Gate (NASA, Guaranteed Job, 100% employment claims, guarantee claims)
const hasUnsupportedClaims = /(?:nasa|ناسا|تضمن|guarantee)/i.test(normLower);

if (relevant.length > 0) {
  const sorted = [...relevant].sort((a, b) => (b.relevance_score || 0) - (a.relevance_score || 0));
  const top = sorted[0];
  const topScore = Number(top.relevance_score || 0);
  const semanticScore = Number(top.semantic_score || 0);
  const lexicalScore = Number(top.lexical_score || 0);

  // Lexical / Category connection verification
  const hasLexicalEvidence = lexicalScore >= 6;
  const hasSemanticEvidence = semanticScore >= 14;
  const hasContentEvidence = Number(top.content_match_count || 0) >= 1 || Number(top.keyword_match_count || 0) >= 1;
  const explicitTopicEvidence = Boolean(topicCategory) && (top.category === topicCategory || (top.category || '').includes(topicCategory));

  let confidence = 'none';
  let action = 'SAFE_DEFLECTION';
  let evidenceSupported = false;

  if (!hasUnsupportedClaims) {
    if (explicitTopicEvidence || (hasLexicalEvidence && topScore >= 18) || (hasContentEvidence && topScore >= 20)) {
      confidence = topScore >= 25 ? 'high' : 'medium';
      action = 'ANSWER';
      evidenceSupported = true;
    } else if (hasSemanticEvidence && (hasLexicalEvidence || hasContentEvidence)) {
      confidence = 'medium';
      action = 'ANSWER';
      evidenceSupported = true;
    }
  }

  // Curate clean internal DEPI context
  const context = sorted.slice(0, 3).map(kb => {
    const q = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);
    const a = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
    const attribution = kb.source_attribution || 'Source attribution unavailable';
    const url = kb.source_url ? `\nSource URL: ${kb.source_url}` : '';
    return `[${kb.program}|${kb.retrieval_scope}] Source: ${attribution}${url}\nسؤال: ${q}\nإجابة: ${a}`;
  }).join('\n---\n');

  const defaultSource = 'مبادرة رواد مصر الرقمية (DEPI)';
  const topCuratedAnswer = isAr ? (top.answer_ar || top.answer) : (top.answer || top.answer_ar);

  return [{
    json: {
      status: action === 'ANSWER' ? 'rag_context_found' : 'low_evidence',
      action: action,
      intent_handled: 'faq_query',
      program_scope: 'DEPI',
      is_ambiguous: false,
      evidence_supported: evidenceSupported,
      rag_context: action === 'ANSWER' ? context : '',
      curated_answer: action === 'ANSWER' ? topCuratedAnswer : '',
      faq_exact_match: topScore >= 18,
      official_source: true,
      customer_message: customerMsg,
      locale: locale,
      top_category: top.category || 'general',
      relevance_score: topScore,
      confidence: confidence,
      confidence_label: confidence.toUpperCase(),
      retrieval_status: action === 'ANSWER' ? 'context_found' : 'low_evidence',
      matched_entries: sorted.length,
      top_program: 'DEPI',
      source_attribution: top.source_attribution || defaultSource,
      retrieval_scope: top.retrieval_scope,
      source_url: top.source_url || 'https://depi.gov.eg',
      validation: { status: 'passed' }
    }
  }];
} else {
  return [{
    json: {
      status: 'no_context',
      action: 'SAFE_DEFLECTION',
      intent_handled: 'faq_query',
      program_scope: 'DEPI',
      is_ambiguous: false,
      evidence_supported: false,
      rag_context: '',
      curated_answer: '',
      faq_exact_match: false,
      official_source: false,
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0,
      confidence: 'none',
      confidence_label: 'NONE',
      request_id: detectorData.request_id || null,
      execution_id: detectorData.execution_id || null,
      channel: detectorData.channel || 'webchat',
      channel_user_id: detectorData.channel_user_id || null,
      customer: detectorData.customer || null,
      conversation: detectorData.conversation || null,
      pii_detected: detectorData.pii_detected || false,
      ai_output: detectorData.ai_output || {},
      retrieval_status: 'no_context',
      matched_entries: 0,
      source_attribution: 'مبادرة رواد مصر الرقمية (DEPI)',
      validation: { status: 'no_context', reason: 'no_relevant_kb_entry' }
    }
  }];
}

/* === ARCHITECTURAL RESPONSE VALIDATOR & DEPI GUARDRAIL === */
const ragData = $('Format RAG Knowledge Response').first()?.json || {};
const qwenItem = $input.first()?.json || {};
const qwenRaw = qwenItem.response;
const llmStatus = qwenRaw && !qwenItem.error && !qwenItem.errorMessage ? 'succeeded' : 'failed';
const llmLatencyMs = Number.isFinite(Number(qwenItem.total_duration)) ? Math.round(Number(qwenItem.total_duration) / 1000000) : null;
const locale = ragData.locale || 'ar';
const isAr = locale === 'ar';
const programScope = ragData.program_scope || 'DEPI';
const confidence = ragData.confidence || 'none';
const action = ragData.action || 'SAFE_DEFLECTION';
const evidenceSupported = Boolean(ragData.evidence_supported);

// --- MODIFIED: Direct out-of-scope reply handling ---
if (ragData.is_out_of_scope || ragData.status === 'out_of_scope') {
  return [{
    json: {
      status: 'out_of_scope',
      intent_handled: 'faq_query',
      program: programScope,
      category: 'out_of_scope',
      reply: ragData.curated_answer, // This contains the out_of_scope_reply
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: 'out_of_scope' },
      confidence: 'high',
      confidence_label: 'HIGH',
      guardrail_decision: 'out_of_scope_deflection',
      requires_human: false,
      llm_status: 'not_needed'
    }
  }];
}
// --- END MODIFIED ---

// 2. Safe Deflection Text (DEPI-focused)
const safeFallbackAR = 'شكراً على استفسارك. يختص نظامنا بالمعلومات المعتمدة لمبادرة رواد مصر الرقمية (DEPI). لم نعثر على معلومات كافية وموثقة تغطي هذا الاستفسار في قاعدة المعرفة المعتمدة حالياً. يمكنك زيارة البوابة الرسمية: https://depi.gov.eg أو التواصل مع الدعم الفني.';
const safeFallbackEN = 'Thank you for your inquiry. Our platform is specialized in the Digital Egypt Pioneers Initiative (DEPI). Sufficient verified information covering this request was not found in our current knowledge base. Please visit the official portal: https://depi.gov.eg or contact technical support.';
const safeDeflection = isAr ? safeFallbackAR : safeFallbackEN;

// --- MODIFIED: Strict Evidence Gate Enforcement ---
if (action === 'SAFE_DEFLECTION' || confidence === 'none' || !evidenceSupported || ragData.status === 'no_context' || ragData.status === 'low_evidence') {
  return [{
    json: {
      status: 'deflection',
      intent_handled: 'faq_query',
      program: programScope,
      category: 'general',
      reply: safeDeflection,
      sources: ['مبادرة رواد مصر الرقمية (DEPI)'],
      validation: { status: 'safe_deflected', confidence: 'none' },
      confidence: 'none',
      confidence_label: 'NONE',
      guardrail_decision: 'safe_deflection'
    }
  }];
}
// --- END MODIFIED ---

// 4. Parse Structured Model Response
let synthesizedAnswer = '';
let isGrounded = true;

if (qwenRaw) {
  try {
    const parsed = typeof qwenRaw === 'string' ? JSON.parse(qwenRaw.trim()) : qwenRaw;
    if (parsed && typeof parsed === 'object' && parsed.answer && parsed.answer.trim()) {
      synthesizedAnswer = parsed.answer.trim();
      isGrounded = parsed.grounded === true;
    } else {
      isGrounded = false;
    }

    // Grounding verification: Guard against self-asserted unsupported claims (e.g. NASA, guaranteed jobs)
    if (/(?:nasa|ناسا|تضمن.*وظيفة|تضمن.*التوظيف|guarantee.*job|guarantee.*employment)/i.test(synthesizedAnswer)) {
      isGrounded = false;
    }

    const trimmedAnswer = synthesizedAnswer.trim();
    const endsOnContinuation = /[\u060C,:\uFF1A\-\u2013\u2014]\s*$/.test(trimmedAnswer);
    const belowUsefulLength = trimmedAnswer.length < (isAr ? 30 : 60);
    if (!trimmedAnswer || endsOnContinuation || belowUsefulLength) {
      isGrounded = false;
    }
  } catch (e) {
    isGrounded = false;
    synthesizedAnswer = '';
  }
} else {
  isGrounded = false;
}

// 5. Fail closed to verified curated answer if LLM failed or was ungrounded
let finalReply = synthesizedAnswer;
let guardrailDecision = 'grounded_llm';
let responseStatus = 'success';

if (llmStatus !== 'succeeded' || !synthesizedAnswer || !isGrounded) {
  if (ragData.curated_answer && (ragData.action === 'ANSWER' || confidence === 'high' || confidence === 'medium')) {
    finalReply = ragData.curated_answer;
    guardrailDecision = 'verified_faq_fallback';
    responseStatus = 'fallback';
  } else {
    finalReply = safeDeflection;
    guardrailDecision = 'safe_deflection';
    responseStatus = 'deflection';
  }
}

// Sanitization
finalReply = finalReply
  .replace(/\[(?:DEBI|DIGILIANS|COMMON|GENERAL|COMPARISON|DEPI)\]\s*/g, '')
  .replace(/سؤال:\s*/g, '')
  .replace(/إجابة:\s*/g, '')
  .replace(/^Q:\s*/gm, '')
  .replace(/^A:\s*/gm, '')
  .replace(/---\n?/g, '\n')
  .replace(/\*\*/g, '*')
  .replace(/^#+\s*/gm, '')
  .trim();

const sourceAttribution = 'مبادرة رواد مصر الرقمية (DEPI)';

return [{
  json: {
    status: responseStatus,
    intent_handled: 'faq_query',
    program: programScope,
    category: ragData.top_category || 'general',
    reply: finalReply,
    sources: [sourceAttribution],
    validation: {
      status: guardrailDecision === 'grounded_llm' ? 'passed' : guardrailDecision,
      confidence: confidence,
      relevance_score: ragData.relevance_score || 0,
      guardrail_decision: guardrailDecision
    },
    confidence: confidence,
    confidence_label: ragData.confidence_label || 'HIGH',
    guardrail_decision: guardrailDecision,
    llm_status: llmStatus,
    llm_latency_ms: llmLatencyMs,
    retrieved_count: ragData.matched_entries || 0,
    source_url: ragData.source_url || 'https://depi.gov.eg',
    customer_message: ragData.customer_message || ''
  }
}];
